    let text = match fs::read_to_string(path) {
        Ok(t) => t,
        Err(e) => return Err(ConfigError::Io(e)),
    };
    let cfg = match toml::from_str(&text) {
        Ok(c) => c,
        Err(e) => return Err(ConfigError::Parse(e)),
    };
